        x,
        y,
        z: safeZoom,
        url: `https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/${safeZoom}/${y}/${x}`,
        minLng: tileMinLng,
        maxLng: tileMaxLng,
        minLat: tileMinLat,
        maxLat: tileMaxLat,
      });
    }
  }

  return tiles;
}
